import{_ as l,C as e,o as r,c as i,a3 as s,E as t,w as d}from"./chunks/framework.Cc-oPviL.js";const f=JSON.parse('{"title":"计算机八股文","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/index.md","filePath":"bagu/index.md"}'),c={name:"bagu/index.md"};function _(h,a,u,g,p,m){const o=e("ModuleTable"),n=e("ClientOnly");return r(),i("div",null,[a[0]||(a[0]=s('<h1 id="计算机八股文" tabindex="-1">计算机八股文 <a class="header-anchor" href="#计算机八股文" aria-label="Permalink to &quot;计算机八股文&quot;">​</a></h1><p>一个月，把「上过课但忘了」的操作系统、网络、数据结构、数据库重新挂回一张网；再加上 AI 应用岗常问的 Python 与工程（GIL、生成器、装饰器、异步）。</p><h2 id="怎么学" tabindex="-1">怎么学 <a class="header-anchor" href="#怎么学" aria-label="Permalink to &quot;怎么学&quot;">​</a></h2><ol><li><strong>读一篇</strong>：按侧栏顺序，每篇约 60 分钟。重点看「为什么这么设计」——八股的差距不在第一层（是什么），在第二层（为什么这样设计）和第三层（不这样会怎么坏）。</li><li><strong>勾验收</strong>：文末的验收清单逐条勾掉。勾的标准是「不看资料能说出来」，不是「看过了」。</li><li><strong>练本篇</strong>：文章顶部点「练本篇」，把这篇的自测题和面试题过一遍。</li><li><strong>每天复习</strong>：首页「今日待复习」点进去，按间隔复习的节奏回顾旧卡。</li></ol><h2 id="三套类比-全库统一" tabindex="-1">三套类比（全库统一） <a class="header-anchor" href="#三套类比-全库统一" aria-label="Permalink to &quot;三套类比（全库统一）&quot;">​</a></h2><p>同一个词在全库永远指同一件事，这是这套资料能「连起来」的前提：</p><ul><li><strong>餐厅 → 操作系统</strong>：CPU 是灶台，进程是客人点的一桌菜，内存是操作台，磁盘是后厨仓库，调度是排号。</li><li><strong>快递 → 计算机网络</strong>：IP 是收件地址，TCP 是带签收的快递单，DNS 是查地址簿，HTTP 是包裹里装的东西。</li><li><strong>图书馆 → 数据库</strong>：表是书架，索引是索引柜，事务是借还书流程，锁是借出登记本，MVCC 是多版本副本。</li></ul><h2 id="进度" tabindex="-1">进度 <a class="header-anchor" href="#进度" aria-label="Permalink to &quot;进度&quot;">​</a></h2>',8)),t(n,null,{default:d(()=>[t(o,{kb:"bagu"})]),_:1})])}const P=l(c,[["render",_]]);export{f as __pageData,P as default};
